    HotelID          INTEGER PRIMARY KEY,
    Name             TEXT    NOT NULL,
    Location         TEXT    NOT NULL,
    CheckInDateTime  TEXT    NOT NULL,
    CheckOutDateTime TEXT    NOT NULL,
