    UserID           INTEGER PRIMARY KEY,
    FirstName        TEXT    NOT NULL,
    LastName         TEXT    NOT NULL,
    Email            TEXT    NOT NULL,
    Password         TEXT,                         -- masked placeholder in source
    PhoneNumber      TEXT,
    RegistrationDate TEXT    NOT NULL              -- ISO 8601 date
);
